import java.util.ArrayList;
import java.util.List;

class Author {
    private String name;
    public Author(String name) { this.name = name; }
    public String getName() { return name; }
}

class Book {
    private String isbn;
    private String title;
    private Author author; // Association

    public Book(String isbn, String title, Author author) {
        this.isbn = isbn;
        this.title = title;
        this.author = author;
    }
    public String getTitle() { return title; }
    public String getDetails() { return "\"" + title + "\" by " + author.getName(); }
}

class BookCopy {
    private String barcode;
    private Book book; // Reference
    private boolean borrowed = false;

    public BookCopy(String barcode, Book book) {
        this.barcode = barcode;
        this.book = book;
    }
    public boolean isBorrowed() { return borrowed; }
    public void setBorrowed(boolean b) { this.borrowed = b; }
    public String getBarcode() { return barcode; }
    public Book getBook() { return book; }
}

class LibraryMember {
    private String memberId;
    private String name;
    private List<BookCopy> loans = new ArrayList<>(); // Association

    public LibraryMember(String memberId, String name) {
        this.memberId = memberId;
        this.name = name;
    }
    public void addLoan(BookCopy copy) { loans.add(copy); }
    public String getName() { return name; }
    public int getLoanCount() { return loans.size(); }
}

class LibraryBranch {
    private String name;
    private List<BookCopy> inventory = new ArrayList<>(); // Composition

    public LibraryBranch(String name) { this.name = name; }

    public BookCopy registerCopy(String barcode, Book book) {
        BookCopy copy = new BookCopy(barcode, book);
        inventory.add(copy);
        return copy;
    }

    public BookCopy findAvailable(Book book) {
        for (BookCopy c : inventory) {
            if (c.getBook() == book && !c.isBorrowed()) return c;
        }
        return null;
    }
}

public class LibraryCoreDemo {
    public static void main(String[] args) {
        Author knuth = new Author("Donald Knuth");
        Book taocp = new Book("978-0201896831", "The Art of Computer Programming", knuth);

        LibraryBranch mainBranch = new LibraryBranch("Downtown Central");
        mainBranch.registerCopy("CPY-001", taocp);

        LibraryMember reader = new LibraryMember("MEM-501", "Grace");
        BookCopy available = mainBranch.findAvailable(taocp);
        if (available != null) {
            available.setBorrowed(true);
            reader.addLoan(available);
            System.out.println(reader.getName() + " checked out " + available.getBook().getDetails());
        }
    }
}

