class CirculationDesk {
    // Collaborates with LibraryBranch, Book, and LibraryMember
    public boolean checkout(LibraryBranch branch, Book book, LibraryMember member) {
        System.out.println("[Circulation] Processing checkout request for: " + member.getName());
        BookCopy copy = branch.findAvailable(book);
        if (copy == null) {
            System.out.println("[Circulation] REJECTED: No copies available for " + book.getTitle());
            return false;
        }
        copy.setBorrowed(true);
        member.addLoan(copy);
        System.out.println("[Circulation] APPROVED: Issued barcode " + copy.getBarcode() + " to " + member.getName());
        return true;
    }
}

public class CirculationDemo {
    public static void main(String[] args) {
        Author orwell = new Author("George Orwell");
        Book b1984 = new Book("978-0451524935", "1984", orwell);

        LibraryBranch branch = new LibraryBranch("East Wing");
        branch.registerCopy("CPY-101", b1984);

        LibraryMember m1 = new LibraryMember("M1", "Winston");
        LibraryMember m2 = new LibraryMember("M2", "Julia");

        CirculationDesk desk = new CirculationDesk();
        desk.checkout(branch, b1984, m1); // Succeeds
        desk.checkout(branch, b1984, m2); // Fails (no copies left)
    }
}

