class LoanTicket {
    private String barcode;
    private String memberName;
    private int daysLate;
    public LoanTicket(String barcode, String memberName, int daysLate) {
        this.barcode = barcode;
        this.memberName = memberName;
        this.daysLate = daysLate;
    }
    public String getBarcode() { return barcode; }
    public String getMemberName() { return memberName; }
    public int getDaysLate() { return daysLate; }
}

class FinePolicy {
    private double finePerDay = 0.50;
    public double calculateFine(int daysLate) {
        return Math.max(0, daysLate * finePerDay);
    }
}

class ReturnDesk {
    private FinePolicy finePolicy = new FinePolicy();
    public void processReturn(LoanTicket ticket) {
        double fine = finePolicy.calculateFine(ticket.getDaysLate());
        if (fine == 0) {
            System.out.println("[Return] Copy " + ticket.getBarcode() + " returned on time by " + ticket.getMemberName() + ". No fines.");
        } else {
            System.out.println("[Return] Copy " + ticket.getBarcode() + " returned by " + ticket.getMemberName() + " (" + ticket.getDaysLate() + " days late). Fine: $" + String.format("%.2f", fine));
        }
    }
}

public class ReturnApp {
    public static void main(String[] args) {
        ReturnDesk desk = new ReturnDesk();
        desk.processReturn(new LoanTicket("BAR-101", "Alice", 0));
        desk.processReturn(new LoanTicket("BAR-202", "Bob", 5));
    }
}

import java.util.ArrayList;
import java.util.List;

class BranchInventory {
    private String branchName;
    private List<String> barcodes = new ArrayList<>();
    public BranchInventory(String branchName) {
        this.branchName = branchName;
    }
    public String getBranchName() { return branchName; }
    public void addCopy(String bc) { barcodes.add(bc); }
    public boolean removeCopy(String bc) { return barcodes.remove(bc); }
    public String getReport() { return branchName + " stock: " + barcodes; }
}

class InterBranchTransferService {
    public boolean transferCopy(BranchInventory from, BranchInventory to, String barcode) {
        if (from.removeCopy(barcode)) {
            to.addCopy(barcode);
            System.out.println("[Transfer] Successfully moved " + barcode + " to " + to.getBranchName());
            return true;
        } else {
            System.out.println("[Transfer] Failed: Barcode not found at origin");
            return false;
        }
    }
}

public class TransferApp {
    public static void main(String[] args) {
        BranchInventory north = new BranchInventory("North Branch");
        north.addCopy("CPY-90");
        north.addCopy("CPY-91");

        BranchInventory south = new BranchInventory("South Branch");

        InterBranchTransferService transferService = new InterBranchTransferService();
        transferService.transferCopy(north, south, "CPY-90");

        System.out.println(north.getReport());
        System.out.println(south.getReport());
    }
}

