import java.util.ArrayList;
import java.util.List;

class Author {
    private String name;
    public Author(String name) { this.name = name; }
    public String getName() { return name; }
}

class Book {
    private String isbn;
    private String title;
    private Author author;
    public Book(String isbn, String title, Author author) {
        this.isbn = isbn;
        this.title = title;
        this.author = author;
    }
    public String getTitle() { return title;
    }
    public Author getAuthor() { return author; }
}

class BookCopy {
    private String barcode;
    private Book book;
    private boolean borrowed = false;
    public BookCopy(String barcode, Book book) {
        this.barcode = barcode;
        this.book = book;
    }
    public boolean isBorrowed() { return borrowed; }
    public void setBorrowed(boolean b) { this.borrowed = b; }
    public String getBarcode() { return barcode; }
    public Book getBook() { return book; }
}

class Member {
    private String memberId;
    private String name;
    private List<BookCopy> activeLoans = new ArrayList<>();
    public Member(String memberId, String name) {
        this.memberId = memberId;
        this.name = name;
    }
    public void borrow(BookCopy copy) { activeLoans.add(copy); }
    public String getName() { return name; }
    public int getLoanCount() { return activeLoans.size(); }
}

class LibraryBranch {
    private String branchName;
    private List<BookCopy> shelfCopies = new ArrayList<>();
    public LibraryBranch(String branchName) {
        this.branchName = branchName;
    }
    public void acquireCopy(String barcode, Book book) {
        shelfCopies.add(new BookCopy(barcode, book));
    }
    public BookCopy borrowBook(Book book) {
        for (BookCopy c : shelfCopies) {
            if (c.getBook() == book && !c.isBorrowed()) {
                c.setBorrowed(true);
                return c;
            }
        }
        return null;
    }
}

public class LibraryApp {
    public static void main(String[] args) {
        Author author = new Author("Robert C. Martin");
        Book book = new Book("978-0134494166", "Clean Architecture", author);

        LibraryBranch branch = new LibraryBranch("City Central Library");
        branch.acquireCopy("BARCODE-001", book);
        branch.acquireCopy("BARCODE-002", book);

        Member alice = new Member("MEM-1", "Alice");
        BookCopy copy = branch.borrowBook(book);
        if (copy != null) {
            alice.borrow(copy);
            System.out.println("[Loan Confirmed] " + alice.getName() + " borrowed: \"" + book.getTitle() + "\" (Copy: " + copy.getBarcode() + ")");
        }
        System.out.println("Alice active loans: " + alice.getLoanCount());
    }
}
